import { useTheme } from '@/app/providers/ThemeProvider'
import { Sun, Moon, Monitor } from 'lucide-react'
import { clsx } from 'clsx'

const accents = ['blue', 'violet', 'emerald', 'amber', 'rose']

export function AppearancePage() {
  const { mode, setMode } = useTheme() as any
  return (
    <div className="h-full overflow-y-auto p-6">
      <div className="max-w-2xl mx-auto">
        <h2 className="font-semibold mb-1">Appearance</h2>
        <p className="text-sm text-muted-foreground mb-6">Customize the look and feel</p>

        <div className="bg-surface rounded-xl border border-border p-5 mb-4">
          <h3 className="text-sm font-medium mb-3">Theme</h3>
          <div className="grid grid-cols-3 gap-2">
            {[
              { id: 'light', label: 'Light', icon: <Sun size={14} /> },
              { id: 'dark', label: 'Dark', icon: <Moon size={14} /> },
              { id: 'system', label: 'System', icon: <Monitor size={14} /> },
            ].map((t) => (
              <button key={t.id} onClick={() => setMode?.(t.id)}
                className={clsx('flex items-center justify-center gap-2 py-2.5 rounded-lg border text-sm transition-colors',
                  mode === t.id ? 'border-accent bg-accent/10 text-accent' : 'border-border text-muted-foreground hover:text-foreground')}>
                {t.icon} {t.label}
              </button>
            ))}
          </div>
        </div>

        <div className="bg-surface rounded-xl border border-border p-5">
          <h3 className="text-sm font-medium mb-3">Accent color</h3>
          <div className="flex gap-3">
            {accents.map((a) => (
              <button key={a} className={`w-8 h-8 rounded-full border-2 border-border hover:border-foreground transition-colors`} style={{ background: `var(--${a}, hsl(var(--accent)))` }} title={a} />
            ))}
          </div>
        </div>
      </div>
    </div>
  )
}
